def construct(budget_seconds, start):
    t0 = time.process_time()
    N = 256
    u = (np.arange(N) + 0.5) / N - 0.5
    s1 = np.sin(2 * np.pi * u)
    c1 = np.cos(2 * np.pi * u)
    s2 = np.sin(4 * np.pi * u)
    c2 = np.cos(4 * np.pi * u)

    def make_h(p):
        a1, b1, a2, b2 = p
        z = a1 * s1 + b1 * c1 + a2 * s2 + b2 * c2
        z = z - z.max()
        return np.exp(z)

    def obj(p):
        return _C(make_h(p))

    x0 = np.array([0.85, 0.0, 0.0, 0.0])
    best_p = x0.copy()
    best_c = obj(x0)

    if start is not None:
        try:
            hs = np.asarray(start, dtype=float)
            if hs.size > 0 and hs.sum() > 0:
                cs = _C(hs)
                if cs < best_c:
                    best_c = cs
        except Exception:
            pass

    def cb(p):
        nonlocal best_p, best_c
        c = obj(p)
        if c < best_c:
            best_c = c
            best_p = p.copy()

    # Reserve time
    deadline = budget_seconds * 0.85
    try:
        res = minimize(obj, x0, method='Nelder-Mead',
                       options={'maxiter': 2000, 'xatol': 1e-4, 'fatol': 1e-6},
                       callback=cb)
        if res.fun < best_c:
            best_c = res.fun
            best_p = res.x.copy()
    except Exception:
        pass

    # A few restarts if time allows
    restarts = [np.array([1.0, 0.1, 0.0, 0.0]),
                np.array([0.7, -0.1, 0.1, 0.0]),
                np.array([0.9, 0.05, 0.05, 0.05])]
    for r in restarts:
        if time.process_time() - t0 > deadline:
            break
        try:
            res = minimize(obj, r, method='Nelder-Mead',
                           options={'maxiter': 1000, 'xatol': 1e-4, 'fatol': 1e-6},
                           callback=cb)
            if res.fun < best_c:
                best_c = res.fun
                best_p = res.x.copy()
        except Exception:
            pass

    h = make_h(best_p)
    if start is not None:
        try:
            hs = np.asarray(start, dtype=float)
            if hs.size > 0 and hs.sum() > 0 and _C(hs) < _C(h):
                return hs
        except Exception:
            pass
    return h

