from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    N = 512
    u = (np.arange(N) + 0.5) / N - 0.5

    # Basis: 4 harmonics, sin and cos
    basis = []
    for k in range(1, 5):
        basis.append(np.sin(2 * np.pi * k * u))
        basis.append(np.cos(2 * np.pi * k * u))
    B = np.stack(basis, axis=1)  # (N, 8)

    def make_h(p):
        z = B @ p
        z = np.clip(z, -50.0, 50.0)
        z = z - z.max()
        return np.exp(z)

    def obj(p):
        return _C(make_h(p))

    # Initialize by least-squares fit to log(start upsampled)
    p0 = np.zeros(8)
    if start is not None:
        try:
            hs = np.asarray(start, dtype=float)
            if hs.size > 0 and hs.sum() > 0:
                # upsample start to N via linear interpolation
                xs = (np.arange(hs.size) + 0.5) / hs.size - 0.5
                hup = np.interp(u, xs, hs)
                hup = np.maximum(hup, 1e-12)
                logh = np.log(hup)
                logh = logh - logh.max()
                # least squares: B p ~ logh
                p0, *_ = np.linalg.lstsq(B, logh, rcond=None)
        except Exception:
            p0 = np.zeros(8)
    else:
        p0 = np.zeros(8)
        p0[0] = 0.85

    best_p = p0.copy()
    best_c = obj(p0)

    # Also consider start directly
    if start is not None:
        try:
            hs = np.asarray(start, dtype=float)
            if hs.size > 0 and hs.sum() > 0:
                cs = _C(hs)
                if cs < best_c:
                    best_c = cs
                    best_p = None  # marker: use start directly
        except Exception:
            pass

    deadline = budget_seconds * 0.90

    def cb(p):
        nonlocal best_p, best_c
        c = obj(p)
        if c < best_c:
            best_c = c
            best_p = p.copy()

    # Nelder-Mead from fit
    try:
        res = minimize(obj, p0, method='Nelder-Mead',
                       options={'maxiter': 4000, 'xatol': 1e-5, 'fatol': 1e-8},
                       callback=cb)
        if res.fun < best_c:
            best_c = res.fun
            best_p = res.x.copy()
    except Exception:
        pass

    # Powell refinement
    if time.process_time() - t0 < deadline:
        try:
            x0 = best_p if best_p is not None else p0
            res = minimize(obj, x0, method='Powell',
                           options={'maxiter': 2000, 'xtol': 1e-5, 'ftol': 1e-8},
                           callback=cb)
            if res.fun < best_c:
                best_c = res.fun
                best_p = res.x.copy()
        except Exception:
            pass

    # A few restarts if time allows
    restarts = []
    if best_p is not None:
        r1 = best_p.copy(); r1[0] += 0.1
        r2 = best_p.copy(); r2[2] += 0.1
        r3 = best_p.copy(); r3[4] += 0.05
        restarts = [r1, r2, r3]
    for r in restarts:
        if time.process_time() - t0 > deadline:
            break
        try:
            res = minimize(obj, r, method='Nelder-Mead',
                           options={'maxiter': 1500, 'xatol': 1e-5, 'fatol': 1e-8},
                           callback=cb)
            if res.fun < best_c:
                best_c = res.fun
                best_p = res.x.copy()
        except Exception:
            pass

    if best_p is None:
        # start was best; return it
        hs = np.asarray(start, dtype=float)
        return hs

    h = make_h(best_p)
    if start is not None:
        try:
            hs = np.asarray(start, dtype=float)
            if hs.size > 0 and hs.sum() > 0 and _C(hs) < _C(h):
                return hs
        except Exception:
            pass
    return h

