def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds - 1.5

    N = 400
    u = (np.arange(N) + 0.5) / N - 0.5
    knots = np.linspace(-0.5, 0.5, 10)
    bounds = [(0.0, 2.0)] * len(knots)

    def build(v):
        return np.maximum(0.0, np.interp(u, knots, v))

    def obj(v):
        return _C(build(v))

    # Initialize with start if available
    best_h = None
    best_C = np.inf
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.size <= 30000 and np.all(np.isfinite(s)) and s.sum() > 0:
            Cs = _C(s)
            if Cs < best_C:
                best_C = Cs
                best_h = s.copy()

    # Global search with differential evolution
    best_v = None
    try:
        remaining = deadline - time.process_time()
        maxiter = max(1, int(remaining / 0.5))  # rough estimate
        # Cap maxiter to keep within budget; DE with popsize 20 on 10 dims
        maxiter = min(maxiter, 200)
        res = differential_evolution(
            obj, bounds, strategy='best1bin', popsize=20,
            maxiter=maxiter, seed=1, polish=False,
            tol=1e-8, mutation=(0.5, 1.0), recombination=0.7,
            init='latinhypercube'
        )
        if res.fun < best_C:
            best_C = res.fun
            best_v = res.x.copy()
            best_h = build(res.x)
    except Exception:
        pass

    # Nelder-Mead polish from best vector
    if best_v is not None and time.process_time() < deadline:
        try:
            res2 = minimize(obj, best_v, method='Nelder-Mead',
                            options={'maxiter': 5000, 'xatol': 1e-8, 'fatol': 1e-12})
            if res2.fun < best_C:
                best_C = res2.fun
                best_h = build(res2.x)
        except Exception:
            pass

    if best_h is None:
        # fallback
        best_h = np.ones(N)

    return best_h

import numpy as np
import time


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _upsample(h, N):
    n = len(h)
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _peak_flatten(h, eta, iters, deadline):
    N = len(h)
    best = h.copy()
    bestC = _C(best)
    no_improve = 0
    for _ in range(iters):
        if time.process_time() >= deadline:
            break
        q = np.convolve(h, h)
        qmax = q.max()
        if qmax <= 0:
            break
        peak_idx = np.where(q > 0.995 * qmax)[0]
        g = np.zeros(N)
        for p in peak_idx:
            lo = max(0, p - (N - 1))
            hi = min(N - 1, p)
            g[lo:hi + 1] += h[p - hi:p - lo + 1][::-1]
        gmax = g.max()
        if gmax <= 0:
            break
        h = h * np.exp(-eta * g / gmax)
        h = np.maximum(h, 1e-12)
        s = h.sum()
        h = h / s
        c = _C(h)
        if c < bestC - 1e-12:
            best = h.copy()
            bestC = c
            no_improve = 0
        else:
            no_improve += 1
            if no_improve >= 100:
                eta *= 0.8
                no_improve = 0
                if eta < 1e-4:
                    eta = 1e-4
    return best, bestC


def _coord_descent(h, bestC, deadline, rng):
    N = len(h)
    deltas = [0.10, 0.03, 0.01]
    improved = True
    while improved and time.process_time() < deadline:
        improved = False
        perm = rng.permutation(N)
        for i in perm:
            if time.process_time() >= deadline:
                break
            base = h[i]
            if base <= 0:
                continue
            for d in deltas:
                for sign in (1.0, -1.0):
                    h[i] = base * np.exp(sign * d)
                    c = _C(h)
                    if c < bestC - 1e-12:
                        bestC = c
                        improved = True
                        base = h[i]
                    else:
                        h[i] = base
    return h, bestC


def construct(budget_seconds, start):
    deadline = min(budget_seconds - 1.5, 18.0)
    rng = np.random.default_rng(12345)

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        h = np.maximum(h, 0.0)
    else:
        N0 = 100
        u = (np.arange(N0) + 0.5) / N0 - 0.5
        h = np.maximum(0.01, 1.0 + 0.85 * np.sin(2 * np.pi * u))

    N = 400
    if len(h) != N:
        h = _upsample(h, N)
    h = np.maximum(h, 1e-9)
    s = h.sum()
    if s <= 0:
        h = np.ones(N)
        s = h.sum()
    h = h / s

    best = h.copy()
    bestC = _C(best)

    while time.process_time() < deadline:
        h, c = _peak_flatten(h, 0.05, 200, deadline)
        if c < bestC:
            best = h.copy()
            bestC = c
        h, c = _coord_descent(h, c, deadline, rng)
        if c < bestC:
            best = h.copy()
            bestC = c
        if time.process_time() >= deadline:
            break

    return best

