def _polish(h, deadline, deltas=(0.001, 0.0003, 0.0001, 3e-5)):
    """Permuted single-coordinate multiplicative moves, both signs."""
    h = np.asarray(h, dtype=float).copy()
    h = np.maximum(h, 1e-12)
    s = h.sum()
    if s <= 0:
        return h
    h = h / s
    bestC = _C(h)
    N = len(h)
    rng = np.random.default_rng(987654321)
    order = np.arange(N)
    while time.process_time() < deadline:
        improved_any = False
        rng.shuffle(order)
        for d in deltas:
            for i in order:
                if time.process_time() >= deadline:
                    return h
                old = h[i]
                for sign in (1.0, -1.0):
                    newv = old * (1.0 + sign * d)
                    if newv <= 0:
                        continue
                    h[i] = newv
                    s = h.sum()
                    if s <= 0:
                        h[i] = old
                        continue
                    c = _C(h)
                    if c < bestC - 1e-15:
                        bestC = c
                        old = newv
                        improved_any = True
                    else:
                        h[i] = old
        if not improved_any:
            break
    return h


