        h = np.maximum(0.01, 1.0 + 0.85 * np.sin(2 * np.pi * u))

    s = h.sum()
    if s <= 0:
        h = np.ones(len(h))
        s = h.sum()
    h = h / s

    best = _polish(h, deadline)
    return best

import numpy as np
import time


def _C(h):
    s = h.sum()
    if s <= 0:
        return np.inf
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def _upsample(h, N):
    n = len(h)
    x_old = (np.arange(n) + 0.5) / n
    x_new = (np.arange(N) + 0.5) / N
    return np.interp(x_new, x_old, h)


def _flatten(h, iters, etas, N, deadline, K=None):
    best = h.copy()
    bestC = _C(best)
    if K is None:
        K = max(32, int(0.04 * (2 * N - 1)))
    K = min(K, 2 * N - 1)
    for _ in range(iters):
        if time.process_time() >= deadline:
            break
        q = np.convolve(h, h)
        qmax = q.max()
        if qmax <= 0:
            break
        if K < len(q):
            peak_idx = np.argpartition(q, -K)[-K:]
        else:
            peak_idx = np.arange(len(q))
        g = np.zeros(N)
        for p in peak_idx:
            lo = max(0, p - (N - 1))
            hi = min(N - 1, p)
            g[lo:hi + 1] += h[p - hi:p - lo + 1][::-1]
        gmax = g.max()
        if gmax <= 0:
            break
        gn = g / gmax
        step_best = None
        step_bestC = np.inf
        for eta in etas:
            cand = h * np.exp(-eta * gn)
            cand = np.maximum(cand, 1e-12)
            s = cand.sum()
            if s <= 0:
                continue
            cand = cand / s
            c = _C(cand)
            if c < step_bestC:
                step_bestC = c
                step_best = cand
        if step_best is None:
            break
        h = step_best
        if step_bestC < bestC - 1e-12:
            best = h.copy()
            bestC = step_bestC
    return best, bestC


def _polish(h, deltas, deadline):
    """Coordinate polish: try +/- delta on each coordinate, strict acceptance."""
    N = len(h)
    best = h.copy()
    bestC = _C(best)
    for delta in deltas:
        improved = True
        while improved:
            improved = False
            for i in range(N):
                if time.process_time() >= deadline:
                    return best, bestC
                for sign in (1.0, -1.0):
                    cand = best.copy()
                    cand[i] = max(0.0, cand[i] + sign * delta)
                    s = cand.sum()
                    if s <= 0:
                        continue
                    cand = cand / s
                    c = _C(cand)
                    if c < bestC - 1e-14:
                        best = cand
                        bestC = c
                        improved = True
                        break
    return best, bestC


def construct(budget_seconds, start):
    deadline = min(budget_seconds - 1.5, 18.0)

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        h = np.maximum(h, 0.0)
    else:
        N0 = 100
        u = (np.arange(N0) + 0.5) / N0 - 0.5
