            if upper <= 0:
                upper = 0.02 * m
            if upper <= 0:
                continue

            def f(x):
                return _C_fixed(h, i, x)

            try:
                res = minimize_scalar(
                    f, bounds=(0.0, upper), method='bounded',
                    options={'xatol': 1e-8, 'maxiter': 15},
                )
            except Exception:
                continue
            if not res.success and res.fun == np.inf:
                continue
            x = res.x
            if x < 0:
                x = 0.0
            c = _C_fixed(h, i, x)
            if c < bestC - 1e-13:
                h = h.copy()
                h[i] = x
                s = h.sum()
                if s > 0:
                    h /= s
