def _slsqp_active(h, N, K, deadline, maxiter=30):
    """Active-set SLSQP on top-K convolution peaks."""
    q = np.convolve(h, h)
    qmax = q.max()
    if K < len(q):
        peak_idx = np.argpartition(q, -K)[-K:]
    else:
        peak_idx = np.arange(len(q))
    peak_idx = np.sort(peak_idx)
    Kp = len(peak_idx)

    # Variables: x = [h (N), t (1)]
    nv = N + 1

    def obj(x):
        return x[N]

    def obj_grad(x):
        g = np.zeros(nv)
        g[N] = 1.0
        return g

    def con_fun(x):
        hh = x[:N]
        t = x[N]
        qq = np.convolve(hh, hh)
        cons = np.empty(Kp + 1)
        cons[:Kp] = qq[peak_idx] - t
        cons[Kp] = hh.sum() - 1.0
        return cons

    def con_jac(x):
        hh = x[:N]
        J = np.zeros((Kp + 1, nv))
        for r, p in enumerate(peak_idx):
            lo = max(0, p - (N - 1))
            hi = min(N - 1, p)
            # dq_p/dh_k = h[p-k] + h[k-p] for valid indices
            for k in range(lo, hi + 1):
                v = 0.0
                j1 = p - k
                if 0 <= j1 < N:
                    v += hh[j1]
                j2 = k - p
                if 0 <= j2 < N:
                    v += hh[j2]
                J[r, k] = v
            J[r, N] = -1.0
        J[Kp, :N] = 1.0
        return J

    x0 = np.empty(nv)
    x0[:N] = h
    x0[N] = qmax

    bounds = [(0.0, None)] * N + [(0.0, None)]
    constraints = [{'type': 'ineq', 'fun': con_fun, 'jac': con_jac}]

    try:
        res = minimize(obj, x0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=constraints,
                       options={'maxiter': maxiter, 'ftol': 1e-12},
                       callback=None)
        xr = res.x
    except Exception:
        return h, _C(h)

    if not np.all(np.isfinite(xr)):
        return h, _C(h)
    hnew = np.maximum(xr[:N], 0.0)
    s = hnew.sum()
    if s <= 0:
        return h, _C(h)
    hnew /= s
    return hnew, _C(hnew)


