def _sensitivities(h, K=64):
    """Return array of per-index sensitivity to the convolution peak."""
    N = len(h)
    q = np.convolve(h, h)
    # top K peak indices in q
    if K < len(q):
        idx = np.argpartition(q, -K)[-K:]
    else:
        idx = np.arange(len(q))
    sens = np.zeros(N)
    for p in idx:
        # s_i = sum over valid p of (h[p-i] + h[i-p])
        # p-i in [0,N-1] => i in [p-N+1, p]
        lo = max(0, p - N + 1)
        hi = min(N - 1, p)
        if lo <= hi:
            # h[p-i] for i in [lo,hi] -> h[p-lo .. p-hi] reversed
            sens[lo:hi + 1] += h[p - np.arange(lo, hi + 1)]
            # h[i-p] for i in [lo,hi] -> h[lo-p .. hi-p]
            lo2 = max(0, p)
            hi2 = min(N - 1, p + N - 1)
            # i-p in [0,N-1] => i in [p, p+N-1]
            a = max(0, p)
            b = min(N - 1, p + N - 1)
