def _slsqp_active_set(h, bestC, K=128, maxiter=200):
    """SLSQP on (h, t) minimizing t subject to q_p(h) <= t for top-K peaks."""
    N = len(h)
    q = np.convolve(h, h)
    # top-K peak indices
    if K >= len(q):
        peak_idx = np.arange(len(q))
    else:
        peak_idx = np.argpartition(q, -K)[-K:]
    peak_idx = np.sort(peak_idx)
    Kk = len(peak_idx)

    def obj(x):
        return x[N]

    def obj_grad(x):
        g = np.zeros(N + 1)
        g[N] = 1.0
        return g

    def con_fun(x):
        hh = x[:N]
        t = x[N]
        qq = np.convolve(hh, hh)
        vals = qq[peak_idx] - t
        s = hh.sum() - 1.0
        return np.concatenate([vals, [s]])

    def con_jac(x):
        hh = x[:N]
        J = np.zeros((Kk + 1, N + 1))
        # gradient of q_p wrt h: 2 * (h shifted)
        # q_p = sum_k h[k] h[p-k]
        for r, p in enumerate(peak_idx):
            # d q_p / d h[i] = 2 * h[p-i] if 0<=p-i<N else 0 (careful: symmetric)
            # Actually q_p = sum_i h[i] h[p-i], so d/dh[i] = h[p-i] + h[p-i] = 2 h[p-i]
            # but only if both indices valid; if p-i == i then derivative is h[i]*2? 
            # q_p = sum_{i+j=p} h[i]h[j]. d/dh[i] = sum_{j: i+j=p} h[j] = h[p-i] (if valid)
            # plus if j==i term contributes h[i] once more? No: sum_{i+j=p} h[i]h[j],
            # derivative wrt h[i]: terms where first index = i give h[p-i]; terms where second = i give h[p-i].
            # So total 2*h[p-i] if p-i != i, else 1*h[i] (only one term, since i+i=p counted once).
            lo = max(0, p - (N - 1))
            hi = min(N - 1, p)
            # indices i in [lo, hi], p-i in [0,N-1]
            for i in range(lo, hi + 1):
                j = p - i
                if i == j:
                    J[r, i] += hh[i]
                else:
                    J[r, i] += 2.0 * hh[j]
            J[r, N] = -1.0
        J[Kk, :N] = 1.0
        return J

    x0 = np.concatenate([h, [bestC]])
    bounds = [(0.0, None)] * N + [(0.0, None)]
    cons = [{'type': 'ineq', 'fun': con_fun, 'jac': con_jac}]
    try:
        res = minimize(obj, x0, jac=obj_grad, method='SLSQP',
                       bounds=bounds, constraints=cons,
                       options={'maxiter': maxiter, 'ftol': 1e-12})
    except Exception:
        return h, bestC
    if res.x is None:
        return h, bestC
    cand = np.maximum(res.x[:N], 0.0)
    tot = cand.sum()
    if tot <= 0:
        return h, bestC
    cand /= tot
    c = _C(cand)
    if c < bestC - 1e-13:
        return cand, c
    return h, bestC


