        res = minimize(obj, init, method='Powell',
                       bounds=[(0.0, None)] * M,
                       options={'maxiter': 20, 'xtol': 1e-10, 'ftol': 1e-12})
    except Exception:
        return h, bestC
    if time.process_time() >= deadline:
        return h, bestC
    hh = build(res.x)
    if hh is None:
        return h, bestC
    c = _C(hh)
    if c < bestC - 1e-13:
        return hh, c
    return h, bestC


