                cand[i] = max(0.0, x[0])
                cand[j] = max(0.0, x[1])
                tot = cand.sum()
                if tot <= 0:
                    return 1e9
                cand /= tot
                return _C(cand)

            x0 = np.array([h[i], h[j]])
            try:
