                    bestC = c
    return h, bestC


def _exact1d(h, bestC, deadline, rng):
    N = len(h)
    if N < 1:
        return h, bestC
    for i in rng.permutation(N):
        if time.process_time() >= deadline:
            return h, bestC
        hi = h[i]
        ub = max(3.0 * hi, 1e-6)

        def obj(x):
            cand = h.copy()
            cand[i] = max(0.0, x)
            tot = cand.sum()
            if tot <= 0:
                return 1e9
            cand /= tot
            return _C(cand)

