def _knot_smooth(h, bestC, deadline, M=100):
    """Represent h as M interpolated knots on [-0.5,0.5]; Powell over knots."""
    N = len(h)
    # step centers on [-0.25, 0.25]
    centers = (np.arange(N) + 0.5) / N - 0.5
    # knots on [-0.5, 0.5]
    knots = np.linspace(-0.5, 0.5, M)
    # initialize knot values by averaging h over bins
    kv = np.zeros(M)
    edges = np.concatenate(([-0.5], (knots[:-1] + knots[1:]) / 2.0, [0.5]))
    for k in range(M):
        lo, hi = edges[k], edges[k + 1]
        mask = (centers >= lo) & (centers < hi)
        if k == M - 1:
            mask = (centers >= lo) & (centers <= hi)
        if np.any(mask):
            kv[k] = h[mask].mean()
        else:
            kv[k] = np.interp(knots[k], centers, h)
    kv = np.maximum(kv, 0.0)

    ub = max(3.0 * np.max(h), 1e-6)
    bounds = [(0.0, ub)] * M

    def obj(x):
        if time.process_time() >= deadline:
            raise TimeoutError
        cand = np.interp(centers, knots, np.maximum(x, 0.0))
        cand = np.maximum(cand, 0.0)
        tot = cand.sum()
        if tot <= 0:
            return 1e9
        cand /= tot
        return _C(cand)

    try:
        res = minimize(obj, kv, method='Powell', bounds=bounds,
                       options={'maxiter': 20, 'xtol': 1e-10, 'ftol': 1e-12})
        x = res.x
    except (TimeoutError, Exception):
        return h, bestC

    cand = np.interp(centers, knots, np.maximum(x, 0.0))
    cand = np.maximum(cand, 0.0)
    tot = cand.sum()
    if tot <= 0:
        return h, bestC
    cand /= tot
    c = _C(cand)
    if c < bestC - 1e-13:
        return cand, c
    return h, bestC


def construct(budget_seconds, start):
    deadline = min(budget_seconds - 1.0, 19.0)

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        h = np.maximum(h, 0.0)
    else:
        N0 = 800
        u = (np.arange(N0) + 0.5) / N0 - 0.5
        h = np.maximum(0.01, 1.0 + 0.85 * np.sin(2 * np.pi * u))

    s = h.sum()
    if s <= 0:
        h = np.ones(len(h))
        s = h.sum()
    h = h / s

    bestC = _C(h)
    rng = np.random.default_rng(98765)

    # Knot smoothing phase
    if time.process_time() < deadline:
        t_ks = min(time.process_time() + 5.0, deadline)
