    # constraints: q_p(x) - t <= 0 for each peak p, and sum(h) - 1 == 0
    def con_fun(x):
        hh = x[:N]
        t = x[N]
        qq = np.convolve(hh, hh)
        c = np.empty(Kk + 1)
        c[:Kk] = qq[idx] - t
        c[Kk] = hh.sum() - 1.0
        return c

    def con_jac(x):
        hh = x[:N]
        J = np.zeros((Kk + 1, N + 1))
        # derivative of q_p wrt h_j: q_p = sum_j h_j h_{p-j}
        # d q_p / d h_j = h_{p-j} + h_{p-j} (with bounds) -> 2*h_{p-j} if valid
        for r, p in enumerate(idx):
            # contributions: q_p = sum_j h_j h_{p-j}
            jlo = max(0, p - (N - 1))
            jhi = min(N - 1, p)
            for j in range(jlo, jhi + 1):
                m = p - j
                if 0 <= m < N:
                    J[r, j] += hh[m]
            J[r, N] = -1.0
        J[Kk, :N] = 1.0
        J[Kk, N] = 0.0
        return J

    x0 = np.empty(N + 1)
    x0[:N] = h
    x0[N] = np.max(q)

    bounds = [(0.0, None)] * N + [(0.0, None)]
    constraints = [{'type': 'ineq', 'fun': lambda x: -con_fun(x),
                    'jac': lambda x: -con_jac(x)}]

    try:
        res = minimize(obj, x0, method='SLSQP', jac=jac,
                       bounds=bounds, constraints=constraints,
                       options={'maxiter': maxiter, 'ftol': 1e-12})
    except Exception:
        return h, bestC
    if res.x is None:
        return h, bestC
    cand = np.maximum(res.x[:N], 0.0)
    tot = cand.sum()
    if tot <= 0:
        return h, bestC
    cand /= tot
    c = _C(cand)
    if c < bestC - 1e-13:
        return cand, c
    return h, bestC


def construct(budget_seconds, start):
    deadline = min(budget_seconds - 1.0, 19.0)

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        h = np.maximum(h, 0.0)
    else:
