def _triple_targeted(h, bestC, deadline, rng, K=64, maxiter=40):
    """Targeted triples: pick i near active convolution peaks."""
    N = len(h)
    if N < 3:
        return h, bestC
    while time.process_time() < deadline:
        q = np.convolve(h, h)
        # top K peak indices of q
        if len(q) > K:
            idx = np.argpartition(q, -K)[-K:]
        else:
            idx = np.arange(len(q))
        # score each candidate i
        scores = []
        cands = []
        for p in idx:
            # i = p - k for k in {0,1,2}? derive i from peak position p
