            break
        scores = np.array(scores)
        cands = np.array(cands)
        # top 25%
        ntop = max(1, len(scores) // 4)
        top = np.argpartition(scores, -ntop)[-ntop:]
        i = int(cands[rng.integers(0, len(top))] if False else cands[top[rng.integers(0, ntop)]])
        d = 1 if rng.random() < 0.5 else -1
        j = i + d
        k = i + 2 * d
