            cand = h.copy()
            cand[i] = max(0.0, x[0])
            cand[j] = max(0.0, x[1])
            cand[k] = max(0.0, x[2])
            tot = cand.sum()
            if tot <= 0:
                return 1e9
            cand /= tot
            return _C(cand)

        x0 = np.array([h[i], h[j], h[k]])
        try:
            res = minimize(obj, x0, method='Nelder-Mead',
                           options={'maxiter': maxiter, 'xatol': 1e-10,
                                    'fatol': 1e-12})
        except Exception:
            continue
        if res.fun < bestC - 1e-13:
            cand = h.copy()
            cand[i] = max(0.0, res.x[0])
            cand[j] = max(0.0, res.x[1])
            cand[k] = max(0.0, res.x[2])
            tot = cand.sum()
            if tot <= 0:
                continue
            cand /= tot
            c = _C(cand)
            if c < bestC - 1e-13:
                h = cand
                bestC = c
    return h, bestC


def _exact1d(h, bestC, deadline, rng):
    N = len(h)
    if N < 1:
        return h, bestC
    for i in rng.permutation(N):
        if time.process_time() >= deadline:
