def _active_peak_flow(h, bestC, deadline, K=32,
                      etas=(0.02, 0.01, 0.005, 0.0025, 0.00125)):
    """p0079-style multiplicative flow on active-peak gradient direction."""
    N = len(h)
    if N < 2:
        return h, bestC
    while time.process_time() < deadline:
        q = np.convolve(h, h)
        m = q.max()
        if K < len(q):
            idx = np.argpartition(q, -K)[-K:]
        else:
            idx = np.arange(len(q))
        g = np.zeros(N)
        for p in idx:
            lo = max(0, p - (N - 1))
            hi = min(p, N - 1)
            if lo <= hi:
                g[lo:hi + 1] += h[(p - np.arange(lo, hi + 1))]
            lo2 = max(0, p)
            hi2 = min(N - 1, p + N - 1)
            if lo2 <= hi2:
                g[lo2:hi2 + 1] += h[np.arange(lo2, hi2 + 1) - p]
        gmax = g.max()
        if gmax <= 0:
            return h, bestC
        g = g / gmax

        best_cand = None
        best_cand_C = bestC
        for eta in etas:
            cand = h * np.exp(-eta * g)
            cand = np.maximum(cand, 1e-12)
            s = cand.sum()
            if s <= 0:
                continue
            cand /= s
            c = _C(cand)
            if c < best_cand_C - 1e-14:
                best_cand = cand
                best_cand_C = c
        if best_cand is None:
            return h, bestC
        h = best_cand
        bestC = best_cand_C
    return h, bestC


