        ub = max(3.0 * hi, 1e-6)

        def obj(x):
            cand = h.copy()
            cand[i] = max(0.0, x)
            tot = cand.sum()
            if tot <= 0:
                return 1e9
            cand /= tot
            return _C(cand)

        try:
            res = minimize_scalar(obj, method='bounded',
                                  bounds=(0.0, ub),
                                  options={'xatol': 1e-12, 'maxiter': 50})
        except Exception:
            continue
        if res.fun < bestC - 1e-13:
            cand = h.copy()
            cand[i] = max(0.0, res.x)
            tot = cand.sum()
            if tot <= 0:
                continue
            cand /= tot
            c = _C(cand)
            if c < bestC - 1e-13:
                h = cand
                bestC = c
    return h, bestC


def _active_peak_flow(h, bestC, deadline, rng, K=32):
    """Multiplicative flow driven by the K largest autoconvolution peaks."""
    N = len(h)
    if N < 2:
        return h, bestC
    etas = (0.02, 0.01, 0.005, 0.0025, 0.00125)
    while time.process_time() < deadline:
        q = np.convolve(h, h)
        if len(q) <= K:
            peaks = np.arange(len(q))
        else:
            peaks = np.argpartition(q, -K)[-K:]
        g = np.zeros(N)
        for p in peaks:
            p = int(p)
            # g_i += h[p-i] + h[i-p], valid indices only
            lo = max(0, p - (N - 1))
            hi = min(N - 1, p)
            if lo <= hi:
                idx = np.arange(lo, hi + 1)
                g[idx] += h[p - idx]
            lo2 = max(0, p - (N - 1))
            hi2 = min(N - 1, p)
            if lo2 <= hi2:
                idx2 = np.arange(lo2, hi2 + 1)
                g[idx2] += h[idx2 - p]
        gm = g.max()
        if gm <= 0:
            break
        g /= gm
        improved = False
        for eta in etas:
            if time.process_time() >= deadline:
                return h, bestC
            cand = h * np.exp(-eta * g)
            cand = np.maximum(cand, 0.0)
            tot = cand.sum()
            if tot <= 0:
                continue
            cand /= tot
            c = _C(cand)
            if c < bestC - 1e-13:
                h = cand
                bestC = c
                improved = True
                break
        if not improved:
            break
    return h, bestC


def construct(budget_seconds, start):
    deadline = min(budget_seconds - 1.0, 19.0)

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        h = np.maximum(h, 0.0)
    else:
        N0 = 800
        u = (np.arange(N0) + 0.5) / N0 - 0.5
        h = np.maximum(0.01, 1.0 + 0.85 * np.sin(2 * np.pi * u))

    s = h.sum()
    if s <= 0:
        h = np.ones(len(h))
        s = h.sum()
    h = h / s

    bestC = _C(h)
    rng = np.random.default_rng(98765)

    # Phase 1: local sweep, adjacent triples, adjacent quads, exact 1D
    t_local = min(6.0, deadline)
    h, bestC = _local_sweep(h, bestC, t_local, rng, max_d=3, maxiter=20)
    if time.process_time() < deadline:
        t_tadj = min(time.process_time() + 2.0, deadline)
        h, bestC = _triple_adj(h, bestC, t_tadj, rng)
    if time.process_time() < deadline:
        t_qadj = min(time.process_time() + 3.0, deadline)
        h, bestC = _quad_adj(h, bestC, t_qadj, rng)
    if time.process_time() < deadline:
        t_e1 = min(time.process_time() + 1.5, deadline)
