            def obj(x):
                cand = h.copy()
                cand[i] = max(0.0, x[0])
                cand[j] = max(0.0, x[1])
                tot = cand.sum()
                if tot <= 0:
                    return 1e9
                cand /= tot
                return _C(cand)

            x0 = np.array([h[i], h[j]])
            try:
                res = minimize(obj, x0, method='Nelder-Mead',
                               options={'maxiter': maxiter, 'xatol': 1e-10,
                                        'fatol': 1e-12})
            except Exception:
                continue
            if res.fun < bestC - 1e-13:
                cand = h.copy()
                cand[i] = max(0.0, res.x[0])
                cand[j] = max(0.0, res.x[1])
                tot = cand.sum()
                if tot <= 0:
                    continue
                cand /= tot
                c = _C(cand)
                if c < bestC - 1e-13:
                    h = cand
                    bestC = c
    return h, bestC


def _triple_adj(h, bestC, deadline, rng, strides=(1, 2), maxiter=40):
    N = len(h)
    if N < 3:
        return h, bestC
    for d in strides:
        if N - 3 - d < 0:
            continue
        order = rng.permutation(N - 3 - d + 1)
        for i in order:
            if time.process_time() >= deadline:
                return h, bestC
            j = i + d
            k = i + 2 * d

            def obj(x):
                cand = h.copy()
                cand[i] = max(0.0, x[0])
                cand[j] = max(0.0, x[1])
                cand[k] = max(0.0, x[2])
                tot = cand.sum()
                if tot <= 0:
                    return 1e9
                cand /= tot
                return _C(cand)

            x0 = np.array([h[i], h[j], h[k]])
            try:
                res = minimize(obj, x0, method='Nelder-Mead',
                               options={'maxiter': maxiter, 'xatol': 1e-10,
                                        'fatol': 1e-12})
            except Exception:
                continue
            if res.fun < bestC - 1e-13:
                cand = h.copy()
                cand[i] = max(0.0, res.x[0])
                cand[j] = max(0.0, res.x[1])
                cand[k] = max(0.0, res.x[2])
                tot = cand.sum()
                if tot <= 0:
                    continue
                cand /= tot
                c = _C(cand)
                if c < bestC - 1e-13:
                    h = cand
                    bestC = c
    return h, bestC


def _quad_adj(h, bestC, deadline, rng, strides=(1, 2), maxiter=40):
    N = len(h)
    if N < 4:
        return h, bestC
    for d in strides:
        if N - 3 * d < 1:
            continue
        order = rng.permutation(N - 3 * d)
        for i in order:
            if time.process_time() >= deadline:
                return h, bestC
            j = i + d
            k = i + 2 * d
            l = i + 3 * d

            def obj(x):
                cand = h.copy()
                cand[i] = max(0.0, x[0])
                cand[j] = max(0.0, x[1])
                cand[k] = max(0.0, x[2])
                cand[l] = max(0.0, x[3])
                tot = cand.sum()
                if tot <= 0:
                    return 1e9
                cand /= tot
                return _C(cand)

            x0 = np.array([h[i], h[j], h[k], h[l]])
            try:
                res = minimize(obj, x0, method='Nelder-Mead',
                               options={'maxiter': maxiter, 'xatol': 1e-10,
                                        'fatol': 1e-12})
            except Exception:
                continue
            if res.fun < bestC - 1e-13:
                cand = h.copy()
                cand[i] = max(0.0, res.x[0])
                cand[j] = max(0.0, res.x[1])
                cand[k] = max(0.0, res.x[2])
                cand[l] = max(0.0, res.x[3])
                tot = cand.sum()
                if tot <= 0:
                    continue
                cand /= tot
                c = _C(cand)
                if c < bestC - 1e-13:
                    h = cand
                    bestC = c
    return h, bestC


def _triple_polish(h, bestC, deadline, rng):
    N = len(h)
    if N < 3:
        return h, bestC
    while time.process_time() < deadline:
        i, j, k = rng.integers(0, N, size=3)
        if i == j or j == k or i == k:
            continue

        def obj(x):
            cand = h.copy()
            cand[i] = max(0.0, x[0])
            cand[j] = max(0.0, x[1])
            cand[k] = max(0.0, x[2])
            tot = cand.sum()
            if tot <= 0:
                return 1e9
            cand /= tot
            return _C(cand)

        x0 = np.array([h[i], h[j], h[k]])
        try:
            res = minimize(obj, x0, method='Nelder-Mead',
                           options={'maxiter': 40, 'xatol': 1e-10,
                                    'fatol': 1e-12})
        except Exception:
            continue
        if res.fun < bestC - 1e-13:
            cand = h.copy()
            cand[i] = max(0.0, res.x[0])
            cand[j] = max(0.0, res.x[1])
            cand[k] = max(0.0, res.x[2])
            tot = cand.sum()
            if tot <= 0:
                continue
            cand /= tot
            c = _C(cand)
            if c < bestC - 1e-13:
                h = cand
                bestC = c
    return h, bestC


def _exact1d(h, bestC, deadline, rng):
    N = len(h)
    if N < 1:
        return h, bestC
    for i in rng.permutation(N):
        if time.process_time() >= deadline:
            return h, bestC
        hi = h[i]
        ub = max(3.0 * hi, 1e-6)

        def obj(x):
            cand = h.copy()
            cand[i] = max(0.0, x)
            tot = cand.sum()
            if tot <= 0:
                return 1e9
            cand /= tot
            return _C(cand)

        try:
            res = minimize_scalar(obj, method='bounded',
                                  bounds=(0.0, ub),
                                  options={'xatol': 1e-12, 'maxiter': 50})
        except Exception:
            continue
        if res.fun < bestC - 1e-13:
            cand = h.copy()
            cand[i] = max(0.0, res.x)
            tot = cand.sum()
            if tot <= 0:
                continue
            cand /= tot
            c = _C(cand)
            if c < bestC - 1e-13:
                h = cand
                bestC = c
    return h, bestC


def _knot_smooth(h, bestC, deadline, M=100):
    """Represent f by M equally spaced knots on [-0.5,0.5], Powell on knots."""
    N = len(h)
    # step centers on [-0.25, 0.25]
    centers = (np.arange(N) + 0.5) / N - 0.5
    knots = np.linspace(-0.5, 0.5, M)
    # initialize knot values by averaging h over corresponding bins
    kv = np.zeros(M)
    cnt = np.zeros(M)
    idx = np.clip(np.searchsorted(knots, centers) - 0, 0, M - 1)
    # assign each center to nearest knot
    idx = np.argmin(np.abs(centers[:, None] - knots[None, :]), axis=1)
    for n in range(N):
        kv[idx[n]] += h[n]
        cnt[idx[n]] += 1
    mask = cnt > 0
    kv[mask] /= cnt[mask]
    if not mask.all():
        # fill empty knots by interpolation
        kv[~mask] = np.interp(knots[~mask], knots[mask], kv[mask])
    s = kv.sum()
    if s > 0:
        kv /= s

    def build(kv_):
        f = np.interp(centers, knots, kv_)
        f = np.maximum(f, 0.0)
        tot = f.sum()
        if tot <= 0:
            return None
        return f / tot

    def obj(kv_):
        f = build(kv_)
        if f is None:
            return 1e9
        return _C(f)

    try:
        res = minimize(obj, kv, method='Powell',
                       options={'maxiter': 200, 'xtol': 1e-10, 'ftol': 1e-12})
        f = build(res.x)
        if f is not None:
            c = _C(f)
            if c < bestC - 1e-14:
                return f, c
    except Exception:
        pass
    return h, bestC


def construct(budget_seconds, start):
    deadline = min(budget_seconds - 1.0, 19.0)

    if start is not None:
        h = np.asarray(start, dtype=float).copy()
        h = np.maximum(h, 0.0)
    else:
        N0 = 800
        u = (np.arange(N0) + 0.5) / N0 - 0.5
        h = np.maximum(0.01, 1.0 + 0.85 * np.sin(2 * np.pi * u))

    s = h.sum()
    if s <= 0:
        h = np.ones(len(h))
        s = h.sum()
    h = h / s

    bestC = _C(h)
    rng = np.random.default_rng(98765)

    # Phase 0 (new): knot smoothing on M=100 knots, up to 4 s
    if time.process_time() < deadline:
        t_knot = min(time.process_time() + 4.0, deadline)
        # temporarily use a deadline-aware wrapper
        h, bestC = _knot_smooth(h, bestC, t_knot, M=100)

    # Phase 1: exact 1D then quad_adj for the remaining time
    if time.process_time() < deadline:
        t_e1 = min(time.process_time() + 2.0, deadline)
        h, bestC = _exact1d(h, bestC, t_e1, rng)
    if time.process_time() < deadline:
        t_qadj = min(time.process_time() + 3.0, deadline)
        h, bestC = _quad_adj(h, bestC, t_qadj, rng)

    # Phase 2: alternate blocks of triples, adjacent triples, adjacent quads,
    # exact 1D, and local sweep
    while time.process_time() < deadline:
        t_tri = min(time.process_time() + 3.0, deadline)
        h, bestC = _triple_polish(h, bestC, t_tri, rng)
        if time.process_time() >= deadline:
            break
        t_tadj = min(time.process_time() + 2.0, deadline)
        h, bestC = _triple_adj(h, bestC, t_tadj, rng)
        if time.process_time() >= deadline:
            break
        t_qadj = min(time.process_time() + 3.0, deadline)
        h, bestC = _quad_adj(h, bestC, t_qadj, rng)
        if time.process_time() >= deadline:
            break
        t_e1 = min(time.process_time() + 1.5, deadline)
        h, bestC = _exact1d(h, bestC, t_e1, rng)
        if time.process_time() >= deadline:
            break
        t_loc = min(time.process_time() + 1.5, deadline)
        h, bestC = _local_sweep(h, bestC, t_loc, rng, max_d=3, maxiter=20)

    return h
